public class Tweet
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid AuthorId { get; set; }
    public string Content { get; set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;
    public int Likes { get; private set; }
    public List<Guid> LikedBy { get; } = new();
}

public class TimelineService
{
    public IEnumerable<Tweet> GetHomeTimeline(Guid userId, int page = 1)
    {
        var following = _follows.GetFollowing(userId);
        return _tweets
            .Where(t => following.Contains(t.AuthorId) || t.AuthorId == userId)
            .OrderByDescending(t => t.CreatedAt)
            .Skip((page - 1) * 20)
            .Take(20);
    }
}
